import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Container for interaction timelines and primitive cleanups
  const timelines = [];
  const primitives = [];

  // Create textured plane (aspect ratio 512:320 ≈ 1.6)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Interaction: hover lift (rise‑in) ----
  const hoverLift = 0.15; // scene units
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL
    .to(
      mesh.position,
      {
        y: `+=${hoverLift}`,
        duration: 0.7,
        ease: 'power3.out',
      },
      0,
    )
    .to(
      mesh.position,
      {
        y: `-=${hoverLift}`,
        duration: 0.2,
        ease: 'power2.out',
        immediateRender: false,
      },
      '+=0.1',
    );
  timelines.push(hoverTL);

  // Attach handlers to userData (no direct DOM listeners)
  root.userData.handlers = {
    hover: () => {
      hoverTL.restart();
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    },
  };

  // ---- Cinematic Primitive: parallax‑scroll ----
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](root, prim.params);
        primitives.push(instance);
      }
    }
  }

  // ---- Cleanup ---------------------------------------------------------------
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    // Cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
    // Dispose three.js resources
    geometry.dispose();
    material.dispose();
  };

  return root;
}
